from decimal import Decimal, InvalidOperation
import re
import json

def transform(value, context):
    def result(status, success, conclusion, warnings=None, catalog=None):
        data = {'success': success, 'conclusion': conclusion, 'questions': [], 'recommendations': []}
        if catalog is not None:
            data['catalog'] = catalog
        return {'business_status': status, 'schema_version': '1.0', 'data': data, 'warnings': warnings or [], 'evidence_refs': []}

    errors = []
    def issue(text):
        if len(errors) < 30:
            errors.append(text)

    def number(raw):
        if not isinstance(raw, str) or not re.fullmatch(r'[0-9]+(?:\.[0-9]+)?', raw):
            raise ValueError('非法十进制数')
        n = Decimal(raw)
        if not n.is_finite():
            raise ValueError('非有限数')
        return n

    tenant = value['tenantId']
    query = value['query_result']
    pages = query['pages']
    if query['complete'] is not True:
        issue('查询未完整结束，禁止基于部分目录推荐。')
    if not pages:
        issue('查询没有返回业务响应页面。')
    if query['page_count'] != len(pages):
        issue('累计页数与实际页面数量不一致。')
    products = []
    observations = []
    seen_products = set()
    seen_skus = set()
    seen_cursors = set()
    for index, page in enumerate(pages):
        label = '第' + str(index + 1) + '页'
        if page.get('tenantId') != tenant:
            issue(label + '租户与查询租户不一致。')
        items = page.get('items')
        if not isinstance(items, list):
            issue(label + '项目列表异常。')
            continue
        if page.get('returnedCount') != len(items):
            issue(label + '返回条数与项目列表不一致。')
        more = page.get('hasMore')
        cursor = page.get('nextCursor')
        if index < len(pages) - 1 and more is not True:
            issue(label + '续页标记与实际分页链不一致。')
        if index == len(pages) - 1 and more is not False:
            issue('末页仍存在续页，目录不完整。')
        if more is True:
            if not isinstance(cursor, str) or not cursor:
                issue(label + '缺少续页游标。')
            elif cursor in seen_cursors:
                issue(label + '续页游标重复。')
            else:
                seen_cursors.add(cursor)
        elif more is False and cursor not in (None, ''):
            issue(label + '末页仍返回非空续页游标。')
        if isinstance(page.get('observedAt'), str):
            observations.append(page['observedAt'])
        else:
            issue(label + '缺少观察时间。')
        for item in items:
            if not isinstance(item, dict):
                issue(label + '存在非对象项目。')
                continue
            pid = item.get('id')
            if not isinstance(pid, str) or not pid.strip():
                issue(label + '项目标识为空。')
            elif pid in seen_products:
                issue(label + '项目标识重复：' + pid)
            else:
                seen_products.add(pid)
            name = item.get('name')
            if not isinstance(name, str) or not name.strip():
                issue(label + '项目缺少可读名称。')
            skus = item.get('skus')
            if not isinstance(skus, list) or not skus:
                issue(label + '项目没有可售规格。')
                continue
            if item.get('availableSkuCount') != len(skus):
                issue(label + '可售规格数量不一致。')
            prices = []
            for sku in skus:
                if not isinstance(sku, dict):
                    issue(label + '存在非对象规格。')
                    continue
                sid = sku.get('id')
                key = (pid, sid) if isinstance(pid, str) and isinstance(sid, str) else None
                if not isinstance(sid, str) or not sid.strip():
                    issue(label + '规格标识为空。')
                elif key in seen_skus:
                    issue(label + '项目内规格标识重复。')
                elif key is not None:
                    seen_skus.add(key)
                for field in ('people', 'players'):
                    n = sku.get(field)
                    if type(n) is not int or n < 1:
                        issue(label + '规格人数违规。')
                try:
                    prices.append(number(sku.get('price')))
                except (ValueError, InvalidOperation, TypeError):
                    issue(label + '规格单价异常。')
                if not isinstance(sku.get('introductionMarkdown'), str):
                    issue(label + '规格介绍结构异常。')
                attrs = sku.get('attributes')
                if not isinstance(attrs, list):
                    issue(label + '规格选项结构异常。')
                elif any(not isinstance(a, dict) or set(a) != {'name', 'value'} for a in attrs):
                    issue(label + '规格选项字段异常。')
            try:
                low = number(item.get('minPrice'))
                high = number(item.get('maxPrice'))
                if low > high or len(prices) != len(skus) or not prices or low != min(prices) or high != max(prices):
                    issue(label + '项目价格范围与规格单价不一致。')
                quantity = item.get('quantity', {})
                qmin = number(quantity.get('min'))
                qmax = number(quantity.get('max'))
                step = number(quantity.get('step'))
                if qmin <= 0 or step <= 0 or qmax < qmin:
                    issue(label + '购买数量上下限或步长违规。')
            except (ValueError, InvalidOperation, TypeError, AttributeError):
                issue(label + '价格或购买数量规则异常。')
            if item.get('priceBasis') != '每个计价单位的整组服务报价':
                issue(label + '报价口径异常。')
            for field in ('billingUnit', 'pricingUnit'):
                unit = item.get(field)
                if not isinstance(unit, dict) or not isinstance(unit.get('name'), str) or not unit['name'].strip():
                    issue(label + '缺少可读计价或记账单位。')
            if not isinstance(item.get('introductionMarkdown'), str):
                issue(label + '项目介绍结构异常。')
            products.append(item)
    if query['received'] != len(products):
        issue('累计条数与实际项目数量不一致。')
    if query['total'] is not None and query['total'] != len(products):
        issue('接口总条数与实际全量项目数量不一致。')
    if errors:
        return result('INSUFFICIENT_DATA', False, '目录检查未通过，已停止推荐。', errors)
    if not products:
        return result('NO_MATCH', False, '该租户当前没有已上架且包含可售规格的项目。')
    catalog = {'tenantId': tenant, 'complete': query['complete'], 'items': products, 'observedAt': observations}
    # 为模型指令、用户需求和结构预留空间；完整目录超限时不截断或挑选部分。
    if len(json.dumps(catalog, ensure_ascii=False, separators=(',', ':')).encode('utf-8')) > 40000:
        return result('INSUFFICIENT_DATA', False, '完整目录超过当前分析容量，请缩小业务范围或使用分批分析流程。', ['目录未截断，未输出部分目录推荐。'])
    return result('COMPLETED', True, '全量目录业务检查通过，可进入项目匹配。', catalog=catalog)

def transform(value, context):
    # 只核对结构化事实，语义匹配理由仍由模型负责。
    result = value['recommendation']
    catalog = value['service_catalog']
    errors = []
    data = result['data']
    recommendations = data['recommendations']
    status = result['business_status']
    pairs = {
        (product['id'], sku['id']): (product, sku)
        for product in catalog['items']
        for sku in product['skus']
    }
    if catalog['complete'] is not True:
        errors.append('推荐所依据的目录不完整。')
    if status == 'COMPLETED':
        if data['success'] is not True or len(recommendations) != 1 or data['questions']:
            errors.append('成功状态必须对应一项推荐且没有待补充问题。')
        if len(recommendations) == 1:
            selected = recommendations[0]
            pair = (selected['product_id'], selected['sku_id'])
            source = pairs.get(pair)
            if source is None:
                errors.append('推荐的项目与规格组合不在已检查目录中。')
            else:
                product, sku = source
                if selected['name'] != product['name']:
                    errors.append('推荐项目名称与目录不一致。')
                if selected['unit_price'] != sku['price']:
                    errors.append('推荐单价未保留目录的原始整组报价。')
                unit = product['billingUnit']['name'] + '/' + product['pricingUnit']['name']
                normalized = selected['price_unit'].replace('／', '/').replace(' ', '')
                if normalized != unit.replace(' ', ''):
                    errors.append('推荐报价单位与目录不一致。')
    elif data['success'] is not False or recommendations:
        errors.append('未完成状态不能包含成功标记或推荐项目。')
    if status == 'NEEDS_INPUT' and not data['questions']:
        errors.append('待补充状态缺少明确问题。')
    if result['evidence_refs']:
        errors.append('当前流程未传入可引用的平台证据对象，证据引用必须为空。')
    if errors:
        return {
            'business_status': 'INSUFFICIENT_DATA',
            'schema_version': '1.0',
            'data': {
                'success': False,
                'conclusion': '推荐结果与目录事实核对未通过，已停止输出推荐。',
                'questions': [],
                'recommendations': [],
            },
            'warnings': errors,
            'evidence_refs': [],
        }
    return result
